function textbookHome(){return `<section class="home-hero"><p class="eyebrow">WESTERN AUSTRALIA · COMPUTER SCIENCE ATAR</p><h1>Learn the ideas.<br>Put them to work.</h1><p class="lede">Your companion from first Python programs to relational databases, secure networks and exam preparation. Read, practise and revisit — one lesson at a time.</p><div class="home-actions"><a class="button" href="resources/">Find your lesson resources →</a><a class="button secondary" href="#contents">Browse all chapters</a></div><p class="home-edition">Years 11 &amp; 12 · Units 1–4 · 2026 foundation, revised for 2027</p></section><section aria-labelledby="home-paths"><p class="eyebrow">MAKE YOUR NEXT STEP</p><h2 id="home-paths">One textbook. More ways to learn.</h2><div class="home-paths"><a class="home-card" href="#contents"><span class="eyebrow">01 / READ</span><h3>Understand a topic</h3><p>50 chapters with explanations, worked examples and practical tasks.</p><span>Open the textbook →</span></a><a class="home-card" href="activities/"><span class="eyebrow">02 / PRACTISE</span><h3>Try it for yourself</h3><p>26 activities across five printable packs, with explained answers and equipment-free options.</p><span>Find an activity →</span></a><a class="home-card" href="sql/"><span class="eyebrow">03 / BUILD SQL SKILLS</span><h3>Query with confidence</h3><p>A sequenced pathway with downloadable databases, expected results and troubleshooting.</p><span>Follow the SQL pathway →</span></a><a class="home-card" href="revision/"><span class="eyebrow">04 / REVISIT</span><h3>Check what you know</h3><p>Topic checklists, retrieval practice, cumulative quizzes and explained exam-style responses.</p><span>Start revision →</span></a></div></section><section class="home-units" aria-labelledby="home-unit-heading"><h2 id="home-unit-heading">Find your place in the course</h2><div class="home-unit-grid">${units.map(u=>`<a class="home-unit" href="#${({1:'start',2:'database-foundations',3:'unit3-fluency',4:'unit4-design'})[u.n]}"><span class="eyebrow">YEAR ${u.year} · UNIT ${u.n}</span><h3>${u.title}</h3><p>${u.desc}</p><span>Start Unit ${u.n} →</span></a>`).join('')}</div></section><section class="home-offline"><p class="eyebrow">TAKE YOUR LEARNING WITH YOU</p><h2>Unreliable internet?<br>Keep a copy.</h2><p>Download a single-file unit reader, printable activity sheets or the complete resource library before you leave school.</p><a class="button" href="offline/">Choose an offline download →</a><p class="small">Clearly labelled formats, file sizes and instructions. No account required.</p></section><section class="home-teacher"><div><p class="eyebrow">FOR TEACHERS</p><h2>Plan around your classroom.</h2><p>Find curriculum mappings, prerequisites, suggested pacing, common misconceptions and equipment alternatives. The drone, VR and network-pod pathway is a separate companion to the general textbook.</p></div><p><a class="button secondary" href="teachers/">Open teacher planning →</a></p></section><p class="notice"><strong>2027 teaching draft.</strong> Built on the 2026 foundation. Teacher review and classroom trials continue. <a href="#audits">Inspect coverage and review status</a>; <a href="#sources">check the syllabus basis and reuse terms</a>.</p>`;}
