const terms={Accumulator:'A variable that combines values during repeated processing.',Array:'An indexed collection; these examples use Python lists for array-style tasks.',Bit:'One binary digit.',Byte:'Eight bits.',Encoding:'A rule for representing text as stored or transmitted data.',Index:'A position used to access an element; Python lists start at zero.',Scope:'The region in which a name can be resolved.',Validation:'Checking that input meets defined rules.',Algorithm:'A precise set of steps for solving a problem.',Argument:'A value supplied when a function is called.',Boolean:'A data type with two values: True and False.',Condition:'An expression evaluated as true or false to make a decision.',Iteration:'Repeating a set of instructions.',Parameter:'A named variable in a function definition that receives an argument.',Selection:'Choosing a path through an algorithm according to a condition.',Sequence:'Executing instructions in order.',Variable:'A name that refers to a value in a program.'};
